#!/usr/bin/env python3
"""Bind the two analysis tasks to immutable inputs and a two-job queue."""
from pathlib import Path
import json,hashlib,shutil
P=Path(__file__).resolve().parent
src=Path('/home/michael/gowin/ref/TangMega-138KPro-example/sfp+/docs/SET_5351.md')
shutil.copyfile(src,P/'glm/task/context/SIPEED_SET_5351.md')
(P/'glm/task/context/WEB_SOURCES.md').write_text('Primary sources checked 2026-10-29:\nhttps://en.wiki.sipeed.com/hardware/en/tang/tang-mega-138k/mega-138k-pro.html\nhttps://github.com/sipeed/TangMega-138KPro-example/blob/main/sfp%2B/docs/SET_5351.md\nSipeed debugger is BL616 exposing FTDI-compatible interfaces, not proof of a physical FT2232. Board revision on hardware is unverified.\n')
contracts={
'deepseek':'''# Exact R5/G22 reset and clock graph — independent analysis
All work offline. Only owned/findings.json and owned/REPORT.md are writable. Inputs are exact snapshots, no hardware/RTL/build edits. Read all relevant top.v/reset.v/soc.v and *_cone.json. The primitive cones include all USB startup counter/FF cells, PLLs, serializers, pullup and combinational ancestors; expansion stops at external FF boundaries. They are NOT a complete payload data cone. Mark every omitted/opaque boundary; do not infer internal AE350/DDR reset from names alone.
Trace board clk->PLL_F lock/delay->PLL_B/960MHz+60MHz->phy qualification->rst_usb->controller PHY_RESET->PHY calibration/reset_calib->CLKDIV/DHCE/OSER/IDES and the TBUF/pad enables. Separate vid_hrstn and DDR/CPU from enumeration prerequisites. Explain the real 104000/64-cycle release sequencers and stopped clock behavior from code, not assumptions. Map LED observable functions and UART pin; identify what can be observed without CDC/J-Link. Use exact primitive pins and output functions, not any new timing attribution. G22 twice enumerated, R3/R5 none; new ROM not necessary.
Produce findings.json {edges:[{build,cell,pin,net}], domains:[{name,clock,reset,source}], observations:[{name,source,limit}], limitations:[strings]}. At least30 true primitive-pin edges from BOTH builds including PLL/reset/pullup/CLKDIV/serializer boundaries. Edges are source connections, not automatic logical influence assertions. REPORT.md must show causal branches, source file/line references, incomplete boundaries, minimal discriminating experiment using existing bitstreams only, no hardware execution. No claim parameter equality proves live clocks or logic/delay equivalence. Tests only validate references, independent reviewer judges causality. Run protected tests before edit then after FINAL report edit. New code <=1000 lines. Finish once deliverables done; no repeated speculative variants.
''',
'glm':'''# Primary-document reset/startup and existing observability audit
Only owned/findings.json and owned/REPORT.md writable, no hardware or network, no RTL/build changes. Read context primary Gowin UG704/SUG100/UG306 excerpts (each has PDF page labels), ProDock4071f schematic, actual G22/R5 top and CST. Scope: does background_programming=off have established relevance to SRAM user startup? distinguish JTAG configuration/boundary SAMPLE observability from GAO instrumentation and CPU JTAG. No defaults invented: if option's implicit default unknown say unknown. Find available read-only board observations when CDC absent: six LEDs logical/polarity, actual UART F19 vs debugger pins P15/N16, possibility of boundary scan user-mode SAMPLE without EXTEST/reset (only recommend if documented exact instruction exists, otherwise pending). BL616 emulates FTDI, don't assume actual FT2232. Root hardware says G22 twice USB+CPU PASS, R3/R5 no attach; don't claim documented facts prove cause.
Produce findings.json {claims:[{id,text,source,quote,status}], experiments:[{name,precondition,observation,limit}], unknowns:[strings]}. At least8 claims with exact source basename in context and exact verbatim nonempty short quote present in that file (case and whitespace may normalize in tests). status documented/inference/unknown. Separate voltage probing highimpedance passive from intrusive scans. No hardware command execution; concrete root procedure should identify serial2025071717 and prohibit JLink506005083/oldboard/flash/EXTEST. REPORT.md cites primary PDF pages and source lines. Quotes short, paraphrase conclusions. Tests validate citations, not truth/causality. Run fixed tests before edit then after FINAL report edit. Keep concise, complete once, no rerun just for prose.
'''}
validators={
'deepseek':'''import json\nfrom pathlib import Path\np=Path(__file__).resolve().parent\nf=json.loads((p/'owned/findings.json').read_text())\nassert len(f.get('edges',[]))>=30\ncs={b:json.loads((p/f'context/{b}_cone.json').read_text())['cells'] for b in ['g22','r5']}\nseen=set()\nfor e in f['edges']:\n assert e['build'] in cs\n assert cs[e['build']][e['cell']]['ports'][e['pin']]==e['net'],e\n seen.add(e['build'])\nassert seen=={'g22','r5'}\nassert len(f.get('domains',[]))>=4 and len(f.get('observations',[]))>=3 and len(f.get('limitations',[]))>=2\nassert len((p/'owned/REPORT.md').read_text())>1500\nprint('PASS exact primitive references and report shape; causal claims require independent review')\n''',
'glm':'''import json,re\nfrom pathlib import Path\np=Path(__file__).resolve().parent\nf=json.loads((p/'owned/findings.json').read_text())\nassert len(f.get('claims',[]))>=8\nnormal=lambda s:re.sub(r'\\s+',' ',s).strip()\nfor c in f['claims']:\n assert c['status'] in ['documented','inference','unknown']\n s=Path(c['source']);assert s.name==str(s) and s.suffix in ['.txt','.v','.cst','.md']\n assert 8<=len(c['quote'])<=600\n assert normal(c['quote']) in normal((p/'context'/s).read_text()),c['id']\nassert len(f.get('experiments',[]))>=2 and len(f.get('unknowns',[]))>=2\nassert len((p/'owned/REPORT.md').read_text())>1500\nprint('PASS source citations and report shape; causal claims require independent review')\n'''}
jobs=[]
for name,model in [('deepseek','deepseek-v4.1-flash'),('glm','glm-5.3-flash')]:
 t=P/name/'task';(t/'CONTRACT.md').write_text(contracts[name]);(t/'validate.py').write_text(validators[name])
 inputs=sorted(str(x.relative_to(P)) for x in t.rglob('*') if x.is_file())
 spec={'schema':1,'execution_mode':'execution','task_id':f'r5_reset_{name}_01','domain':'fpga','task_type':'reset_observability','difficulty':'high','inputs':inputs,'owned':[f'{name}/task/owned/findings.json',f'{name}/task/owned/REPORT.md'],'tests':[['/usr/bin/python3','-B',f'{name}/task/validate.py']],'timeout_seconds':30,'require_initial_failure':True,'require_changes':True,'max_continuations':0,'required_tool_evidence':{'failed_test_before_edit':True,'passed_test_after_edit':True},'acceptance_criteria':'Source-bound findings and useful discriminating observation plan, exact inputs preserved, no cause claimed from static similarity','prompt':f'Read {name}/task/CONTRACT.md and actual inputs. Run fixed tests before editing. Perform the complete bounded analysis, write only the owned outputs. Run fixed tests after the last report edit. No hardware, network, new bitstream or shared edits. Do not spend the session on generic methodology; deliver evidence.'}
 f=P/name/'spec.json';f.write_text(json.dumps(spec,indent=2)+'\n')
 jobs.append({k:spec[k] for k in ['execution_mode','task_id','domain','task_type','difficulty','acceptance_criteria']}|{'run_id':f'r5_reset_{name}_20261029_01','model':model,'packet':str(f.relative_to(P)),'packet_sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'after':[]})
(P/'queue.json').write_text(json.dumps({'schema':1,'max_active':2,'jobs':jobs},indent=2)+'\n')
runner=Path('/home/michael/.codex/model-workflow/agent_runner.py')
print(hashlib.sha256(runner.read_bytes()).hexdigest())
